fn solve(a: i8, b: i8, c: i8) -> i8 {
    // Work in i32 for safety and simplicity
    let mut x = [a as i32, b as i32, c as i32];
    x.sort_unstable();

    // We'll try making all equal to T, where T is at least the current max.
    // Since each operation adds total +2 across the three numbers, the final total
    // must have the same parity as the initial total.
    //
    // Also, if we can reach T, the number of operations is (3*T - sum)/2.
    //
    // It suffices to try T in [max .. max+2] (parity + small adjustment).
    let sum = x[0] + x[1] + x[2];
    let maxv = x[2];

    let mut best = i32::MAX;

    for t in maxv..=maxv + 2 {
        // Parity condition: total increase = 3*t - sum must be even
        let total_inc = 3 * t - sum;
        if total_inc < 0 || total_inc % 2 != 0 {
            continue;
        }

        let d0 = t - x[0];
        let d1 = t - x[1];
        let d2 = t - x[2];
        if d0 < 0 || d1 < 0 || d2 < 0 {
            continue;
        }

        // Feasibility condition:
        // In each op, any single number can increase by at most 2.
        // So for each i: di <= 2*k, where k = total_inc/2.
        let k = total_inc / 2;
        if d0 <= 2 * k && d1 <= 2 * k && d2 <= 2 * k {
            best = best.min(k);
        }
    }

    // Given constraints, best will always be found.
    best as i8
}